  void WorldUtilities(){var city=empire.Snapshot.City;var r=empire.ForecastCity();var m=Studio.Modal(root,"POWER & OPERATING CAPACITY",WorldDesk);Studio.Image(m,"power",250,200,220,220);Studio.Label(m,r.PowerDemand+" DEMAND / "+r.PowerAvailable+" SUPPLY\n\nInsufficient capacity reduces output and service limits. Grid electricity is billed daily; local generation has its own upkeep. Winter raises grid prices.\n\nImprove the public connection or build local generation once the city can support it.\n\nNext connection: +"+empireConfig.City.GridCapacity+" capacity\nPermit: "+CityMoney(city.GridTier*200),44,475,632,525,30,Studio.Text,TextAlignmentOptions.Center);Studio.Button(m,"IMPROVE CONNECTION",44,1100,632,125,()=>WorldAction(()=>empire.ImproveCityGrid(Guid.NewGuid().ToString("N"),EmpireNow)),true);}
  void WorldHelp(){var m=Studio.Modal(root,"YOUR CITY,ONE DAY AT A TIME",WorldDesk);Studio.Label(m,"Start with empty land. Build homes before residents arrive. Households differ in age,retirement,budget and interests;each dwelling holds up to 4 people. Only occupied homes pay rent.\n\nChildren create no coffee orders. Working-age residents can take jobs;retirees cannot. Adults buy according to preferences and their remaining household budget.\n\nCafés use beans and cups to serve coffee. Their cash income is reduced by wages,power,deliveries,imports and taxes. Competition,price and walking distance affect demand.\n\nBuild farms,warehouses and utilities when their benefits outweigh their running costs. Ports can import,export genuine surplus and bring visitors for hotels.\n\nTap empty plots to build. Tap a business to inspect its margin,price,pause or move it. Changes made during a day apply tomorrow.\n\nZoom,pan and buy adjacent land to develop this same city. Operating days begin quickly and later take longer. There is no skip. You can plan while businesses operate.",44,235,632,810,26,Studio.Text);Studio.Button(m,"MY CITY",44,1110,632,110,PermanentCityScreen,true);}
